 1  import { Chip, TextField } from '@mui/material';
 2  import { Autocomplete } from '@mui/material';
 3  import { Label, LABELS } from '../data/issues';
 4  
 5  // What a screen reader hears (and the snackbar shows) after a change.
 6  const ANNOUNCEMENTS: Record<string, (label: Label) => string> = {
 7    'select-option': (label) => `Added “${label.name}”`,
 8    'remove-option': (label) => `Removed “${label.name}”`,
 9  };
10  
11  interface LabelPickerProps {
12    value: Label[];
13    onChange: (labels: Label[]) => void;
14    onAnnounce?: (message: string, label: Label) => void;
15  }
16  
17  export function LabelPicker({ value, onChange, onAnnounce }: LabelPickerProps) {
18    return (
19      <Autocomplete
20        multiple
21        options={LABELS}
22        value={value}
23        getOptionLabel={(label) => label.name}
24        isOptionEqualToValue={(option, selected) => option.id === selected.id}
25        filterSelectedOptions
26        onChange={(_event, labels, reason, details) => {
27          onChange(labels);
28          const announce = ANNOUNCEMENTS[reason];
29          if (announce && details) onAnnounce?.(announce(details.option), details.option);
30        }}
31        renderTags={(labels, getTagProps) =>
32          labels.map((label, index) => (
33            <Chip size="small" label={label.name} {...getTagProps({ index })} key={label.id} />
34          ))
35        }
36        renderInput={(params) => <TextField {...params} label="Labels" variant="outlined" />}
37      />
38    );
39  }
